patches.ocaml-signal-stack.patch:
--- /tmp/dynetikat-v11-linux/signals_nat.c.original	2026-11-21 14:08:40.228053658 +0330
+++ runtime/signals_nat.c	2026-11-21 14:08:40.229643890 +0330
@@ -182,7 +182,7 @@
 #ifdef HAS_STACK_OVERFLOW_DETECTION

 static char * system_stack_top;
-static char sig_alt_stack[SIGSTKSZ];
+static char sig_alt_stack[64 * 1024];

 #if defined(SYS_linux)
 /* PR#4746: recent Linux kernels with support for stack randomization
@@ -276,7 +276,7 @@
     stack_t stk;
     struct sigaction act;
     stk.ss_sp = sig_alt_stack;
-    stk.ss_size = SIGSTKSZ;
+    stk.ss_size = sizeof(sig_alt_stack);
     stk.ss_flags = 0;
     SET_SIGACT(act, segv_handler);
     act.sa_flags |= SA_ONSTACK | SA_NODEFER;
